            mod = self.modules.get(name)
            if mod:
                parts.append(f"## {name}\n```json\n{json.dumps(mod, ensure_ascii=False, indent=2)}\n```\n")
            else:
                parts.append(f"## {name}\n_(не загружен)_\n")
