            --green-bright: #34d399;
            --green-neon: #6ee7b7;
            --green-glow: rgba(16,185,129,0.12);
            --violet: #7c3aed;
            --violet-soft: #a78bfa;
            --violet-dim: rgba(124,58,237,0.12);
            --indigo: #3730a3;
            --indigo-soft: #818cf8;
            --text: #dcfce7;
            --text-2: #5a8a6a;
            --text-3: #254535;
            --mono: 'Fira Mono', monospace;
            --sans: 'Nunito', sans-serif;
            --copy: #10b981;
            --download: #14b8a6;
            --apply: #a78bfa;
            --radius: 8px;
            --radius-sm: 4px;
        }

        * { margin: 0; padding: 0; box-sizing: border-box; }

        body {
            background: var(--bg);
            color: var(--text);
            font-family: var(--sans);
            font-weight: 300;
            height: 100vh;
            display: flex;
            flex-direction: column;
            overflow: hidden;
            position: relative;
        }

        /* Glow pools */
        .glow-pool {
            position: fixed;
            border-radius: 50%;
            filter: blur(100px);
            pointer-events: none;
        }
        .gp-1 {
            width: 600px; height: 400px;
            top: -100px; right: -200px;
            background: radial-gradient(ellipse, rgba(16,185,129,0.1) 0%, transparent 70%);
            animation: pool-drift 20s ease-in-out infinite alternate;
        }
        .gp-2 {
            width: 400px; height: 400px;
            bottom: -100px; left: -100px;
            background: radial-gradient(ellipse, rgba(124,58,237,0.08) 0%, transparent 70%);
        }
        @keyframes pool-drift {
            from { transform: scale(1) translate(0, 0); }
            to { transform: scale(1.15) translate(-20px, 15px); }
        }

        /* Flower of Life с анимированным градиентом */
        .bg-flower {
            position: fixed;
            right: -220px; top: 50%;
            transform: translateY(-50%);
            width: 700px; height: 700px;
            opacity: 0.35;
            pointer-events: none;
            animation: flower-breathe 8s cubic-bezier(0.45, 0.05, 0.55, 0.95) infinite alternate;
        }
        .bg-flower circle {
            stroke-width: 0.6;
        }
        @keyframes flower-breathe {
            0% { opacity: 0.2; transform: translateY(-50%) scale(0.98); }
            50% { opacity: 0.45; transform: translateY(-50%) scale(1.02); }
            100% { opacity: 0.3; transform: translateY(-50%) scale(1.0); }
        }

        /* Header */
        .header {
            height: 52px;
            border-bottom: 1px solid var(--line);
            display: flex;
            align-items: center;
            justify-content: space-between;
            padding: 0 22px;
            flex-shrink: 0;
            position: relative;
            z-index: 10;
        }
        .header::after {
            content: '';
            position: absolute;
            bottom: -1px; left: 15%; right: 15%;
            height: 1px;
            background: linear-gradient(to right, transparent, var(--green), var(--violet), var(--indigo), transparent);
            opacity: 0.3;
        }

        .h-left { display: flex; align-items: center; gap: 14px; }

        .logo-mark { width: 34px; height: 34px; }
        .logo-mark svg { width: 34px; height: 34px; }

        .brand-text {
            display: flex; flex-direction: column; gap: 1px;
        }
        .brand-name {
            font-family: var(--mono);
            font-size: 11px; font-weight: 400;
            letter-spacing: 2.5px; text-transform: uppercase;
            color: #ffffff;
        }
        .brand-sub {
            font-family: var(--mono);
            font-size: 7px; letter-spacing: 2px; text-transform: uppercase;
            color: #6ee7b7;
        }

        .h-right { display: flex; align-items: center; gap: 12px; }

        .model-display {
            font-family: var(--mono);
            font-size: 9px;
            letter-spacing: 1.5px;
            text-transform: uppercase;
            color: #a7f3d0;
            background: transparent;
            border: 1px solid #2d5a4a;
            padding: 5px 10px;
            border-radius: 6px;
            white-space: nowrap;
        }

        .vsep { width: 1px; height: 18px; background: var(--line); }

        .status-orb {
            display: flex; align-items: center; gap: 6px;
        }
        .orb-dot {
            width: 8px; height: 8px;
            border-radius: 50%;
            background: var(--green-2);
            box-shadow: 0 0 10px var(--green-2), 0 0 20px rgba(16,185,129,0.3);
            animation: orb-pulse 3s ease-in-out infinite;
        }
        @keyframes orb-pulse {
            0%,100% { box-shadow: 0 0 10px var(--green-2), 0 0 20px rgba(16,185,129,0.3); }
            50% { box-shadow: 0 0 6px var(--green-2), 0 0 10px rgba(16,185,129,0.15); }
        }
        .orb-label { display: none; }

        /* Layout */
        .layout { flex: 1; display: flex; overflow: hidden; position: relative; z-index: 1; }

        /* Chat list */
        .chat-list {
            width: 220px;
            border-right: 1px solid var(--line);
            display: flex;
            flex-direction: column;
            overflow: hidden;
            flex-shrink: 0;
        }
        .chat-list-header {
            padding: 16px;
            border-bottom: 1px solid var(--line);
            font-family: var(--mono);
            font-size: 9px;
            letter-spacing: 2px;
            text-transform: uppercase;
            color: var(--green-bright);
            display: flex;
            justify-content: space-between;
            align-items: center;
        }
        .new-chat-btn {
            background: transparent;
            border: 1px solid var(--green-2);
            color: var(--green-bright);
            width: 24px;
            height: 24px;
            border-radius: var(--radius-sm);
            cursor: pointer;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 14px;
            transition: all 0.2s;
        }
        .new-chat-btn:hover {
            background: var(--green-2);
            color: var(--bg);
        }
        .chat-items {
            flex: 1;
            overflow-y: auto;
            padding: 8px;
        }
        .chat-item {
            padding: 10px 12px;
            margin-bottom: 4px;
            border-radius: var(--radius-sm);
            cursor: pointer;
            display: flex;
            align-items: center;
            justify-content: space-between;
            transition: all 0.15s;
            border: 1px solid transparent;
        }
        .chat-item:hover {
            background: var(--surface-2);
            border-color: var(--line-2);
        }
        .chat-item.active {
            background: var(--surface-2);
            border-color: var(--green-2);
        }
        .chat-item-title {
            font-size: 12px;
            color: var(--text);
            flex: 1;
            overflow: hidden;
            text-overflow: ellipsis;
            white-space: nowrap;
        }
        .chat-item-actions {
            display: flex;
            gap: 4px;
            opacity: 0;
            transition: opacity 0.15s;
        }
        .chat-item:hover .chat-item-actions {
            opacity: 1;
        }
        .chat-item-action {
            background: transparent;
            border: none;
            color: var(--text-3);
            cursor: pointer;
            padding: 2px 4px;
            font-size: 10px;
        }
        .chat-item-action:hover {
            color: var(--green-bright);
        }
        .chat-item-action.delete:hover {
            color: #f43f5e;
        }

        /* Content */
        .content { flex: 1; display: flex; flex-direction: column; overflow: hidden; }

        /* Tabs */
        .tabs {
            height: 42px;
            border-bottom: 1px solid var(--line);
            display: flex; align-items: center;
            padding: 0 22px;
            flex-shrink: 0;
            gap: 2px;
        }
        .tab {
            font-family: var(--mono); font-size: 9px;
            letter-spacing: 2px; text-transform: uppercase;
            color: #5a8a6a;
            background: transparent; border: none;
            cursor: pointer; padding: 0 16px; height: 100%;
            display: flex; align-items: center;
            transition: color 0.15s; position: relative;
        }
        .tab:hover { color: #a7f3d0; }
        .tab.active {
            color: #6ee7b7;
            text-shadow: 0 0 5px #10b981;
        }
        .tab.active::after {
            content: '';
            position: absolute;
            bottom: -1px; left: 8px; right: 8px;
            height: 1px;
            background: linear-gradient(to right, transparent, var(--green-2), transparent);
        }

        /* Messages */
        .messages {
            flex: 1;
            overflow-y: auto;
            overflow-x: hidden;
            padding: 28px 22px 20px; /* уменьшен нижний отступ */
            display: flex;
            flex-direction: column;
            gap: 20px;
        }

        .msg {
            display: flex; gap: 13px;
            max-width: 82%;
            min-width: 0;
            animation: mup 0.28s ease;
        }
        @keyframes mup {
            from { opacity: 0; transform: translateY(8px); }
            to { opacity: 1; transform: translateY(0); }
        }

        .msg.user { align-self: flex-end; flex-direction: row-reverse; }
        .msg.sys { align-self: center; max-width: 90%; }

        .av { width: 36px; height: 36px; flex-shrink: 0; margin-top: 3px; }
        .av svg { width: 36px; height: 36px; }

        .mbody { display: flex; flex-direction: column; gap: 4px; min-width: 0; }
        .mname {
            font-family: var(--mono); font-size: 8px;
            letter-spacing: 2px; text-transform: uppercase;
            color: var(--text-3);
        }
        .msg.user .mname { text-align: right; }

        .bub {
            padding: 12px 16px;
            font-size: 13.5px; line-height: 1.7; font-weight: 300;
            word-break: break-word;
            overflow-wrap: break-word;
            min-width: 0;
        }
        .msg.assistant .bub {
            background: var(--surface-2);
            border: 1px solid var(--line);
            border-radius: 2px 12px 12px 12px;
            border-left: 2px solid;
            border-image: linear-gradient(to bottom, #10b981, #7c3aed, #3730a3) 1;
            border-image-slice: 1;
        }
        .msg.user .bub {
            background: rgba(124,58,237,0.07);
            border: 1px solid rgba(124,58,237,0.18);
            border-radius: 12px 2px 12px 12px;
            white-space: pre-wrap;
        }
        .msg.sys .bub {
            background: rgba(16,185,129,0.15);
            border: 1px solid rgba(16,185,129,0.4);
            color: #6ee7b7;
            text-shadow: 0 0 8px rgba(16,185,129,0.6);
            font-family: var(--mono);
            font-size: 11px;
            letter-spacing: 2px;
            text-align: center;
            border-radius: 6px;
            padding: 10px 16px;
        }

        /* Code blocks */
        .code-block {
            margin: 12px 0; 
            border: 1px solid var(--line-2); 
            border-radius: var(--radius);
            overflow: hidden; 
            background: var(--surface); 
            box-shadow: 0 4px 20px rgba(0,0,0,0.3);
            max-width: 100%;
            width: 100%;
            box-sizing: border-box;
        }
        .code-header {
            display: flex; 
            align-items: center; 
            justify-content: space-between;
            padding: 6px 12px; 
            background: var(--surface-2); 
            border-bottom: 1px solid var(--line-2);
        }
        .code-lang {
            font-family: var(--mono); 
            font-size: 11px; 
            color: var(--green-bright);
            text-transform: uppercase; 
            letter-spacing: 1px;
        }
        .code-actions { 
            display: flex; 
            gap: 2px; 
            flex-shrink: 0;
            margin-left: auto;
        }
        .code-btn {
            width: 28px;
            height: 24px;
            background: var(--surface); 
            border: 1px solid var(--line-2);
            border-radius: var(--radius-sm); 
            font-size: 12px;
            font-family: var(--mono); 
            cursor: pointer; 
            transition: all 0.15s ease;
            display: flex; 
            align-items: center; 
            justify-content: center;
            line-height: 1; 
        }
        .code-btn.copy { 
            color: var(--copy); 
            border-color: var(--copy); 
        }
        .code-btn.copy:hover { 
            background: var(--copy); 
            color: var(--bg); 
            box-shadow: 0 0 12px var(--copy);
            transform: translateY(-1px);
        }
        .code-btn.download { 
            color: var(--download); 
            border-color: var(--download); 
        }
        .code-btn.download:hover { 
            background: var(--download); 
            color: var(--bg); 
            box-shadow: 0 0 12px var(--download);
            transform: translateY(-1px);
        }
        .code-btn.apply { 
            color: var(--apply); 
            border-color: var(--apply); 
        }
        .code-btn.apply:hover { 
            background: var(--apply); 
            color: var(--bg); 
            box-shadow: 0 0 12px var(--apply);
            transform: translateY(-1px);
        }

        .code-btn.toggle {
            color: var(--text-dim);
            border-color: var(--line-2);
            font-size: 10px;
            letter-spacing: 1px;
        }
        .code-btn.toggle:hover {
            background: var(--surface-2);
            color: var(--text);
            transform: translateY(-1px);
        }
        .code-block.collapsed .code-content {
            display: none;
        }
        .code-block.collapsed .code-header {
            border-bottom: none;
        }
        .code-lines-hint {
            font-family: var(--mono);
            font-size: 10px;
            color: var(--text-dim);
            margin-left: 8px;
            opacity: 0.6;
        }


            padding: 12px; 
            overflow-x: auto; 
            overflow-y: auto;
            background: var(--surface);
            font-family: var(--mono); 
            font-size: 12px; 
            line-height: 1.6;
            color: var(--text); 
            max-height: 400px; 
            white-space: pre-wrap;
            word-break: break-word;
        }

        /* Thinking indicator — опущен ниже */
        .thinking {
            display: flex;
            align-items: center;
            gap: 10px;
            padding: 8px 22px 12px; /* увеличен верхний отступ для приближения к инпуту */
            font-family: var(--mono);
            font-size: 8px;
            letter-spacing: 2px;
            text-transform: uppercase;
            color: var(--green-bright);
            border-top: 1px solid transparent; /* визуально отделим */
            margin-top: auto; /* прижмёт к низу, если контейнер flex column */
        }
        .thinking .logo {
            width: 36px;
            height: 36px;
            background: url('data:image/svg+xml;base64,') center/contain no-repeat;
            animation: spin 1.2s linear infinite;
        }
        @keyframes spin { to { transform: rotate(360deg); } }
        .dots {
            display: inline-block;
        }
        .dots::after {
            content: '';
            display: inline-block;
            width: 2ch;
            animation: dots 1.5s steps(4, end) infinite;
        }
        @keyframes dots {
            0% { content: ''; }
            25% { content: '.'; }
            50% { content: '..'; }
            75% { content: '...'; }
        }

        /* Input area — всегда яркая */
        .input-area {
            padding: 0 22px 18px; /* убран верхний отступ, перенесён в thinking */
            flex-shrink: 0;
        }
        .irow { display: flex; align-items: flex-end; gap: 10px; }

        .ibtn {
            width: 38px; height: 38px;
            background: rgba(16,185,129,0.1);
            border: 2px solid var(--green-2);
            color: var(--green-bright);
            cursor: pointer;
            display: flex; align-items: center; justify-content: center;
            font-size: 16px; flex-shrink: 0; border-radius: 10px;
            transition: all 0.2s;
        }
        .ibtn:hover { 
            background: var(--green-2);
            color: var(--bg);
            box-shadow: 0 0 20px var(--green-2);
            transform: scale(1.05);
        }

        .ifield {
            flex: 1;
            background: var(--surface);
            border: 2px solid var(--green-2);
            border-radius: 10px;
            color: var(--text);
            font-family: var(--sans); font-weight: 300; font-size: 14px;
            padding: 10px 15px; outline: none;
            resize: none; max-height: 120px; line-height: 1.5;
            transition: border-color 0.2s, box-shadow 0.2s, background 0.2s;
        }
        .ifield:focus {
            border-color: var(--violet-soft);
            box-shadow: 0 0 0 3px rgba(124,58,237,0.2);
            background: linear-gradient(145deg, var(--surface), rgba(124,58,237,0.05));
        }
        .ifield::placeholder { color: var(--text-3); }

        .isend {
            background: linear-gradient(145deg, var(--green), var(--violet));
            border: 2px solid transparent;
            color: white;
            box-shadow: 0 4px 20px rgba(124,58,237,0.4);
        }
        .isend:hover {
            background: linear-gradient(145deg, var(--green-2), var(--violet-soft));
            box-shadow: 0 4px 30px rgba(124,58,237,0.7);
        }

        /* Claude observer button */
        .observer-btn {
            background: rgba(59,130,246,0.1);
            border-color: #3b82f6;
            color: #93c5fd;
            font-size: 18px;
        }
        .observer-btn:hover {
            background: #3b82f6;
            color: white;
            box-shadow: 0 0 20px rgba(59,130,246,0.5);
        }
        .observer-btn.active {
            background: linear-gradient(145deg, #1d4ed8, #4f46e5);
            border-color: #60a5fa;
            color: white;
            box-shadow: 0 0 20px rgba(59,130,246,0.6), 0 0 40px rgba(79,70,229,0.3);
            animation: observer-pulse 2s ease-in-out infinite;
        }
        @keyframes observer-pulse {
            0%, 100% { box-shadow: 0 0 20px rgba(59,130,246,0.6); }
            50% { box-shadow: 0 0 30px rgba(59,130,246,0.9), 0 0 50px rgba(79,70,229,0.4); }
        }

        /* Observer message bubble */
        .msg.observer .bub {
            background: rgba(59,130,246,0.07);
            border: 1px solid rgba(59,130,246,0.25);
            border-radius: 2px 12px 12px 12px;
            border-left: 2px solid;
            border-image: linear-gradient(to bottom, #3b82f6, #6366f1, #8b5cf6) 1;
            border-image-slice: 1;
        }
        .msg.observer .mname { color: #60a5fa; }
        .observer-thinking-indicator {
            display: flex; align-items: center; gap: 8px;
            padding: 8px 22px;
            font-family: var(--mono); font-size: 10px;
            color: #60a5fa; opacity: 0.7;
            letter-spacing: 2px;
        }
        .observer-thinking-indicator .dots span {
            animation: dots 1.5s steps(4, end) infinite;
        }


        .file-attachment {
            display: flex;
            flex-direction: column;
            gap: 6px;
            padding: 8px 12px;
            background: var(--surface);
            border: 1px solid var(--line-2);
            border-radius: var(--radius-sm);
            margin: 0 22px 8px;
            font-size: 12px;
            color: var(--text);
        }
        .file-info {
            display: flex;
            align-items: center;
            gap: 8px;
        }
        .file-info .file-icon {
            font-size: 16px;
        }
        .file-info .file-name {
            flex: 1;
            white-space: nowrap;
            overflow: hidden;
            text-overflow: ellipsis;
        }
        .file-info .file-percent {
            font-family: var(--mono);
            color: var(--green-bright);
            min-width: 40px;
            text-align: right;
        }
        .file-info .remove {
            cursor: pointer;
            color: var(--text-3);
        }
        .file-info .remove:hover { color: #f43f5e; }
        .file-progress {
            height: 4px;
            background: var(--line);
            border-radius: 2px;
            overflow: hidden;
        }
        .file-progress-bar {
            height: 100%;
            background: linear-gradient(90deg, var(--green-2), var(--violet-soft));
            width: 0%;
            transition: width 0.3s ease;
        }

        /* Resonance indicator */
        .resonance-indicator {
            display: flex;
            align-items: center;
            gap: 10px;
            padding: 8px 14px;
            margin: 0 22px 10px;
            background: var(--surface-2);
            border: 1px solid var(--line);
            border-radius: var(--radius-sm);
            opacity: 0;
            transform: translateY(-5px);
            transition: all 0.3s ease;
        }
        .resonance-indicator.visible {
            opacity: 1;
            transform: translateY(0);
        }
        .resonance-icon {
            width: 24px;
            height: 24px;
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 12px;
            background: linear-gradient(135deg, var(--green-2), var(--violet));
            flex-shrink: 0;
            animation: resonance-pulse 2s ease-in-out infinite;
        }
        @keyframes resonance-pulse {
            0%, 100% { transform: scale(1); opacity: 0.8; }
            50% { transform: scale(1.08); opacity: 1; }
        }
        .resonance-bar {
            flex: 1;
            height: 4px;
            background: var(--line);
            border-radius: 2px;
            overflow: hidden;
            position: relative;
        }
        .resonance-fill {
            height: 100%;
            background: linear-gradient(90deg, var(--green-2), var(--violet-soft));
            border-radius: 2px;
            transition: width 0.5s ease;
            position: relative;
        }
        .resonance-fill::after {
            content: '';
            position: absolute;
            top: 0; left: 0; right: 0; bottom: 0;
            background: linear-gradient(90deg, transparent, rgba(255,255,255,0.3), transparent);
            animation: shimmer 2s infinite;
        }
        @keyframes shimmer {
            0% { transform: translateX(-100%); }
            100% { transform: translateX(100%); }
        }
        .resonance-value {
            font-family: var(--mono);
            font-size: 11px;
            color: var(--green-bright);
            min-width: 35px;
            text-align: right;
        }
        .resonance-level-low .resonance-fill {
            background: linear-gradient(90deg, #f59e0b, #ef4444);
        }
        .resonance-level-medium .resonance-fill {
            background: linear-gradient(90deg, #14b8a6, var(--green-2));
        }
        .resonance-level-high .resonance-fill {
            background: linear-gradient(90deg, var(--green-2), var(--violet-soft));
        }

        /* File tree */
        #file-tree {
            width: 250px;
            border-right: 1px solid var(--line);
            overflow-y: auto;
            padding: 12px;
            font-family: var(--mono);
            font-size: 11px;
        }
        #file-tree .folder { 
            color: var(--green-bright); 
            cursor: pointer;
            padding: 2px 0;
        }
        #file-tree .file { 
            color: var(--text-2); 
            cursor: pointer; 
            padding-left: 16px;
            padding: 2px 0 2px 16px;
            display: block;
            white-space: nowrap;
            overflow: hidden;
            text-overflow: ellipsis;
        }
        #file-tree .file:hover { 
            color: var(--text); 
            background: var(--green-glow);
        }
        #file-tree .file.selected { 
            color: var(--green-bright); 
            background: var(--green-glow);
        }

        /* Editor container */
        .editor-container {
            flex: 1;
            display: flex;
            flex-direction: column;
            min-width: 0;
        }
        #monaco-editor {
            flex: 1;
            min-height: 0;
            border: none;
        }
        .file-editor-header {
            padding: 8px 16px;
            border-bottom: 1px solid var(--line-2);
            display: flex;
            justify-content: space-between;
            align-items: center;
            background: var(--surface-2);
        }
        .file-editor-header .file-path {
            font-family: var(--mono);
            font-size: 11px;
            color: var(--text-3);
        }
        /* Стиль для кнопки сохранения без текста */
        .file-editor-header .code-btn.apply {
            font-size: 16px; /* символ крупнее */
            width: 32px;
            height: 28px;
        }

        /* Modals */
        .modal-overlay {
            position: fixed; inset: 0; background: rgba(3,13,9,0.9); backdrop-filter: blur(4px);
            display: none; align-items: center; justify-content: center; z-index: 100; padding: 20px;
        }
        .modal-overlay.active { display: flex; }
        .modal {
            background: var(--surface); border: 1px solid var(--line-2); border-radius: var(--radius);
            width: 100%; max-width: 500px; max-height: 80vh; overflow: hidden;
            box-shadow: 0 20px 60px rgba(0,0,0,0.5);
        }
        .modal-header {
            padding: 16px; border-bottom: 1px solid var(--line-2);
            display: flex; align-items: center; justify-content: space-between;
        }
        .modal-title { font-size: 14px; font-weight: 500; color: var(--green-bright); font-family: var(--mono); }
        .modal-close {
            width: 28px; height: 28px; border: none; background: transparent; color: var(--text-3);
            cursor: pointer; border-radius: var(--radius-sm); display: flex; align-items: center; justify-content: center; font-size: 18px;
        }
        .modal-close:hover { color: var(--text); background: var(--surface-2); }
        .modal-body { padding: 16px; overflow-y: auto; }
        .rename-input {
            width: 100%;
            background: var(--surface-2);
            border: 1px solid var(--line-2);
            border-radius: var(--radius-sm);
            padding: 10px 12px;
            color: var(--text);
            font-family: var(--sans);
            font-size: 14px;
            outline: none;
        }
        .rename-input:focus {
            border-color: var(--green-2);
        }
        .patch-preview-box {
            background: var(--surface-2);
            border: 1px solid var(--line-2);
            border-radius: var(--radius-sm);
            padding: 12px;
            max-height: 200px;
            overflow: auto;
        }
        .patch-preview-box pre {
            font-family: var(--mono);
            font-size: 11px;
            line-height: 1.5;
            color: var(--text);
            margin: 0;
        }
        .modal-footer {
            padding: 16px; border-top: 1px solid var(--line-2);
            display: flex; justify-content: flex-end; gap: 10px;
        }
        .btn {
            padding: 8px 16px; border-radius: var(--radius-sm); font-size: 12px; cursor: pointer;
            transition: all 0.15s ease; border: none; font-family: var(--mono);
            text-transform: uppercase; letter-spacing: 0.5px;
        }
        .btn-secondary { background: var(--surface-2); color: var(--text-3); border: 1px solid var(--line-2); }
        .btn-secondary:hover { border-color: var(--green); color: var(--text); }
        .btn-primary { background: var(--surface); color: var(--green-bright); border: 1px solid var(--green); }
        .btn-primary:hover { background: var(--green); color: var(--bg); box-shadow: 0 4px 15px var(--green); }

        /* Seeds tab */
        .seeds-container { flex: 1; overflow-y: auto; padding: 16px; }
        .seeds-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(260px, 1fr)); gap: 12px; }
        .seed-card {
            background: var(--surface); border: 1px solid var(--line-2); border-radius: var(--radius);
            padding: 14px; transition: all 0.15s ease; cursor: pointer;
        }
        .seed-card:hover { border-color: var(--green-2); box-shadow: 0 4px 20px rgba(16,185,129,0.1); }
        .seed-header { display: flex; align-items: flex-start; justify-content: space-between; margin-bottom: 8px; }
        .seed-title { font-size: 13px; font-weight: 500; color: var(--text); }
        .seed-id { font-size: 10px; color: var(--text-3); font-family: var(--mono); }
        .seed-desc { font-size: 12px; color: var(--text-2); line-height: 1.5; margin-bottom: 10px; }
        .seed-meta { display: flex; gap: 6px; font-size: 10px; }
        .seed-badge { padding: 3px 8px; background: var(--surface-2); border-radius: var(--radius-sm); color: var(--text-2); font-family: var(--mono); text-transform: uppercase; letter-spacing: 0.5px; }

        /* Toast */
        .toast {
            position: fixed; bottom: 20px; right: 20px; padding: 12px 20px; background: var(--surface);
            border: 1px solid var(--line-2); border-radius: var(--radius); color: var(--text);
            font-size: 12px; z-index: 200; transform: translateY(100px); opacity: 0;
            transition: all 0.3s ease; font-family: var(--mono); box-shadow: 0 10px 40px rgba(0,0,0,0.3);
        }
        .toast.show { transform: translateY(0); opacity: 1; }
        .toast.success { border-color: var(--green-2); color: var(--green-bright); }
        .toast.error { border-color: #f43f5e; color: #f43f5e; }

        /* Utilities */
        .hidden { display: none !important; }
        .tab-content { display: none; flex: 1; overflow: hidden; }
        .tab-content.active { display: flex; flex-direction: column; }
        code {
            font-family: var(--mono); font-size: 12px; background: var(--surface-2);
            padding: 2px 6px; border-radius: var(--radius-sm); color: var(--green-bright);
        }

        /* Scrollbar */
        ::-webkit-scrollbar { width: 3px; }
        ::-webkit-scrollbar-track { background: transparent; }
        ::-webkit-scrollbar-thumb { background: var(--line-2); border-radius: 2px; }
        ::-webkit-scrollbar-thumb:hover { background: var(--green); }
    </style>
</head>
<body>
