    <!-- Модальные окна -->
    <div class="modal-overlay" id="patchModal">
        <div class="modal">
            <div class="modal-header"><div class="modal-title">◈ ПРИМЕНИТЬ ПАТЧ</div><button class="modal-close" onclick="closePatchModal()">×</button></div>
            <div class="modal-body"><div class="patch-preview-box" id="patchPreviewBox"><pre id="patchPreviewContent">загрузите JSON-патч...</pre></div></div>
            <div class="modal-footer"><button class="btn btn-secondary" onclick="closePatchModal()">отмена</button><button class="btn btn-primary" id="confirmPatchBtn" onclick="confirmPatch()" disabled>применить</button></div>
        </div>
