    <div class="modal-overlay" id="renameModal">
        <div class="modal">
            <div class="modal-header"><div class="modal-title">◈ ПЕРЕИМЕНОВАТЬ ЧАТ</div><button class="modal-close" onclick="closeRenameModal()">×</button></div>
            <div class="modal-body">
                <input type="text" class="rename-input" id="renameInput" placeholder="Новое название" maxlength="50">
            </div>
            <div class="modal-footer">
                <button class="btn btn-secondary" onclick="closeRenameModal()">отмена</button>
                <button class="btn btn-primary" id="confirmRenameBtn" onclick="confirmRename()">сохранить</button>
            </div>
        </div>
