    <input type="file" id="fileInput" accept=".json,.txt,.md,.html,.py,.js,.css" style="display: none" onchange="handleFileSelect(event)" multiple>

    <div class="toast" id="toast"></div>
        <script>
        // ==================== КОНСТАНТЫ ====================
        const WS_URL = 'wss://mandala-engineer-chat.onrender.com/ws';
        const API_BASE = 'https://mandala-engineer-chat.onrender.com'; // базовый URL для API
        const GITHUB_REPO = 'voodoomushroomzzz-source/mandala-core';

        // Глобальные переменные
        let chats = [];
        let currentChatId = null;
        let nextChatId = 1;
        let ws = null;
        let pendingFiles = [];
        let messageBuffer = '';
        let currentMessageDiv = null;
        let currentPatch = null;
        let editor = null; // для Monaco

        // DOM элементы
        const statusDot = document.getElementById('statusDot');
        const messagesEl = document.getElementById('messages');
        const inputEl = document.getElementById('messageInput');
        const sendBtn = document.getElementById('sendBtn');
        const thinkingEl = document.getElementById('thinking');
        const seedsGrid = document.getElementById('seedsGrid');
        const filePreview = document.getElementById('filePreview');
        const fileNameEl = document.getElementById('fileName');
        const filePercentEl = document.getElementById('filePercent');
        const fileProgressBar = document.getElementById('fileProgressBar');
        const chatList = document.getElementById('chatList');
        const fileTree = document.getElementById('file-tree');
        const currentFilePath = document.getElementById('current-file-path');
        const saveFileBtn = document.getElementById('save-file-btn');

        // ==================== ИНИЦИАЛИЗАЦИЯ MONACO ====================
        require.config({ paths: { vs: 'https://cdn.jsdelivr.net/npm/monaco-editor@0.52.2/min/vs' } });
        require(['vs/editor/editor.main'], function() {
            editor = monaco.editor.create(document.getElementById('monaco-editor'), {
                value: '// Выберите файл для редактирования',
                language: 'text',
                theme: 'vs-dark',
                automaticLayout: true,
                minimap: { enabled: false }
            });
        });

        // ==================== ЗАГРУЗКА ЧАТОВ ====================
        function loadChats() {
            const saved = localStorage.getItem('mandala_chats');
            if (saved) {
                try {
                    chats = JSON.parse(saved);
                    nextChatId = Math.max(...chats.map(c => parseInt(c.id.replace('chat_', ''))), 0) + 1;
                } catch (e) {
                    chats = [];
                }
            }
            renderChatList();
        }

        function saveChats() {
            localStorage.setItem('mandala_chats', JSON.stringify(chats));
            chats.forEach(chat => {
                if (chat.messages && chat.messages.length) {
                    localStorage.setItem(`chat_${chat.id}_messages`, JSON.stringify(chat.messages));
                }
            });
        }

        function renderChatList() {
            chatList.innerHTML = chats.map(chat => `
                <div class="chat-item ${chat.id === currentChatId ? 'active' : ''}" onclick="switchChat('${chat.id}')">
                    <span class="chat-item-title">${escapeHtml(chat.name)}</span>
                    <div class="chat-item-actions">
                        <button class="chat-item-action" onclick="renameChat('${chat.id}', event)">✎</button>
                        <button class="chat-item-action delete" onclick="deleteChat('${chat.id}', event)">×</button>
                    </div>
                </div>
            `).join('');
        }

        function createNewChat(name = null) {
            const defaultName = name || `Чат ${nextChatId}`;
            const chatId = 'chat_' + (nextChatId++);
            const newChat = { id: chatId, name: defaultName, created: Date.now(), messages: [] };
            chats.push(newChat);
            saveChats();
            renderChatList();
            switchChat(chatId);
        }

        function switchChat(chatId) {
            if (currentChatId === chatId) return;
            if (currentChatId) saveCurrentChatMessages();
            currentChatId = chatId;
            localStorage.setItem('current_chat_id', chatId);
            const chat = chats.find(c => c.id === chatId);
            if (chat) {
                const savedMessages = localStorage.getItem(`chat_${chatId}_messages`);
                chat.messages = savedMessages ? JSON.parse(savedMessages) : [];
                messagesEl.innerHTML = '';
                if (chat.messages.length > 0) {
                    chat.messages.forEach(msg => {
                        if (msg.role === 'user') addUserMessage(msg.content, false);
                        else if (msg.role === 'assistant') appendFullMessage(msg.content, false);
                        else if (msg.role === 'system') addSystemMessage(msg.content, false);
                    });
                } else {
                    addSystemMessage('🌱 Новый чат. Добро пожаловать!', false);
                }
                renderChatList();
            }
        }

        function saveCurrentChatMessages() {
            if (!currentChatId) return;
            const chat = chats.find(c => c.id === currentChatId);
            if (chat) {
                const messages = [];
                document.querySelectorAll('.msg').forEach(msgEl => {
                    const role = msgEl.classList.contains('user') ? 'user' : 
                                msgEl.classList.contains('sys') ? 'system' : 'assistant';
                    const content = msgEl.querySelector('.bub').innerText;
                    messages.push({ role, content });
                });
                chat.messages = messages;
                localStorage.setItem(`chat_${currentChatId}_messages`, JSON.stringify(messages));
            }
        }

        function renameChat(chatId, event) {
            event.stopPropagation();
            const chat = chats.find(c => c.id === chatId);
            if (!chat) return;
            document.getElementById('renameInput').value = chat.name;
            document.getElementById('renameModal').classList.add('active');
            document.getElementById('confirmRenameBtn').dataset.chatId = chatId;
        }

        function closeRenameModal() {
            document.getElementById('renameModal').classList.remove('active');
        }

        function confirmRename() {
            const chatId = document.getElementById('confirmRenameBtn').dataset.chatId;
            const newName = document.getElementById('renameInput').value.trim();
            if (!chatId || !newName) return;
            const chat = chats.find(c => c.id === chatId);
            if (chat) {
                chat.name = newName;
                saveChats();
                renderChatList();
            }
            closeRenameModal();
        }

        function deleteChat(chatId, event) {
            event.stopPropagation();
            if (chats.length <= 1) {
                showToast('Нельзя удалить последний чат', 'error');
                return;
            }
            const index = chats.findIndex(c => c.id === chatId);
            if (index !== -1) {
                localStorage.removeItem(`chat_${chatId}_messages`);
                chats.splice(index, 1);
                if (currentChatId === chatId) switchChat(chats[0].id);
                else renderChatList();
                saveChats();
            }
        }

        // ==================== WEBSOCKET ====================
        function connect() {
            updateStatus('connecting');
            ws = new WebSocket(WS_URL);
            ws.onopen = () => ws.send(JSON.stringify({ type: 'init', session_id: currentChatId }));
            ws.onmessage = (e) => { try { handleMessage(JSON.parse(e.data)); } catch (ex) { console.error(ex); } };
            ws.onclose = () => { updateStatus('error'); showToast('◈ соединение разорвано', 'error'); setTimeout(connect, 3000); };
            ws.onerror = () => updateStatus('error');
        }

        function updateStatus(state) {
            statusDot.className = 'orb-dot';
            if (state === 'connected') {
                statusDot.style.background = 'var(--green-2)';
                statusDot.style.boxShadow = '0 0 10px var(--green-2), 0 0 20px rgba(16,185,129,0.3)';
            } else if (state === 'connecting') {
                statusDot.style.background = 'var(--violet-soft)';
                statusDot.style.boxShadow = '0 0 8px var(--violet-soft)';
            } else {
                statusDot.style.background = '#f43f5e';
                statusDot.style.boxShadow = '0 0 12px #f43f5e';
            }
        }

        function handleMessage(data) {
            switch(data.type) {
                case 'connected':
                    updateStatus('connected');
                    break;
                case 'history':
                    // Бэкенд восстановил сессию из GitHub — рендерим историю
                    // Пропускаем protected служебные сообщения (инъекция ядра)
                    messagesEl.innerHTML = '';
                    (data.messages || []).forEach(msg => {
                        if (msg.role === 'user') addUserMessage(msg.content, false);
                        else if (msg.role === 'assistant') appendFullMessage(msg.content, false);
                    });
                    scrollToBottom();
                    break;
                case 'system':
                    addSystemMessage(data.text);
                    break;
                case 'stream':
                    handleStream(data.content);
                    break;
                case 'done':
                    finishMessage();
                    break;
                case 'error':
                    showToast(data.text, 'error');
                    hideThinking();
                    finishMessage();
                    break;
                case 'module_direct':
                    showToast(`◈ модуль ${data.name} получен`, 'success');
                    const formatted = `**Модуль ${data.name}:**\n\`\`\`json\n${data.content}\n\`\`\``;
                    appendFullMessage(formatted, true);
                    break;
                case 'modules_refreshed':
                    showToast(`◈ обновлено ${data.count} модулей`, 'success');
                    break;
                case 'file_processed':
                    // Показываем подтверждение в индикаторе
                    fileNameEl.textContent = `✅ ${data.summary}`;
                    fileProgressBar.style.width = '100%';
                    filePercentEl.textContent = '100%';
                    addSystemMessage(data.summary);
                    break;
                case 'patch_result':
                    handlePatchResult(data.results);
                    break;
                case 'resonance':
                    updateResonance(data.value, data.level);
                    break;
                case 'pong':
                    break;
                case 'observer_state':
                    setObserverState(data.active);
                    break;
                case 'observer_thinking':
                    showObserverThinking();
                    break;
                case 'observer_message':
                    hideObserverThinking();
                    addObserverMessage(data.content);
                    break;
                case 'observer_error':
                    hideObserverThinking();
                    showToast('◬ Claude-наблюдатель не ответил', 'error');
                    break;
            }
        }

        // ==================== СООБЩЕНИЯ ====================
        function createMessageElement(role) {
            const div = document.createElement('div');
            div.className = `msg ${role}`;
            const iconSvg = role === 'user' 
                ? '<svg viewBox="0 0 30 30" fill="none"><circle cx="15" cy="15" r="13" stroke="#7c3aed" stroke-width="0.8" opacity="0.4"/><circle cx="15" cy="15" r="6" stroke="#7c3aed" stroke-width="0.8" fill="rgba(124,58,237,0.08)"/><circle cx="15" cy="15" r="2" fill="#a78bfa" opacity="0.6"/></svg>'
                : '<svg viewBox="0 0 30 30" fill="none"><circle cx="15" cy="15" r="7" stroke="#10b981" stroke-width="0.8"/><circle cx="15" cy="8"  r="7" stroke="#10b981" stroke-width="0.8" opacity="0.5"/><circle cx="15" cy="22" r="7" stroke="#10b981" stroke-width="0.8" opacity="0.5"/><circle cx="21.06" cy="11.5" r="7" stroke="#10b981" stroke-width="0.8" opacity="0.5"/><circle cx="21.06" cy="18.5" r="7" stroke="#10b981" stroke-width="0.8" opacity="0.5"/><circle cx="8.94" cy="11.5"  r="7" stroke="#10b981" stroke-width="0.8" opacity="0.5"/><circle cx="8.94" cy="18.5"  r="7" stroke="#10b981" stroke-width="0.8" opacity="0.5"/><circle cx="15" cy="15" r="2" fill="#34d399" opacity="0.9"/></svg>';
