        // ==================== ВКЛАДКА ФАЙЛОВ ====================
        async function loadFileTree() {
            fileTree.innerHTML = 'Загрузка...';
            try {
                const response = await fetch(`${API_BASE}/api/tree`);
                if (!response.ok) {
                    throw new Error(`HTTP ${response.status}`);
                }
                const data = await response.json();
                if (data.error) throw new Error(data.error);
                const tree = buildTree(data.tree);
                fileTree.innerHTML = renderTree(tree);
                document.querySelectorAll('#file-tree .file').forEach(el => {
                    el.addEventListener('click', () => {
                        document.querySelectorAll('#file-tree .file').forEach(f => f.classList.remove('selected'));
                        el.classList.add('selected');
                        loadFile(el.dataset.path);
                    });
                });
            } catch (err) {
                fileTree.innerHTML = `❌ Ошибка загрузки: ${err.message}`;
            }
        }

        function buildTree(files) {
            const root = {};
            files.forEach(file => {
                if (file.type !== 'blob') return;
                const parts = file.path.split('/');
                let current = root;
                parts.forEach((part, i) => {
                    if (i === parts.length - 1) {
                        current[part] = { type: 'file', path: file.path };
                    } else {
                        if (!current[part]) current[part] = { type: 'dir', children: {} };
                        current = current[part].children;
                    }
                });
            });
            return root;
        }

        function renderTree(node, level = 0) {
            if (node.type === 'file') {
                const ext = node.path.split('.').pop();
                return `<div class="file file ${ext}" data-path="${node.path}" style="padding-left: ${level * 16 + 16}px">${node.path.split('/').pop()}</div>`;
            }
            let html = '';
            Object.keys(node).forEach(key => {
                if (key === 'type') return;
                const child = node[key];
                if (child.type === 'dir') {
                    html += `<div class="folder" style="padding-left: ${level * 16}px">${key}</div>`;
                    html += renderTree(child.children, level + 1);
                } else {
                    html += renderTree(child, level + 1);
                }
            });
            return html;
        }

        async function loadFile(path) {
            currentFilePath.textContent = path;
            saveFileBtn.disabled = false;
            try {
                const response = await fetch(`https://raw.githubusercontent.com/${GITHUB_REPO}/main/${path}`);
                if (!response.ok) throw new Error(`HTTP ${response.status}`);
                const content = await response.text();
                const ext = path.split('.').pop();
                const language = ext === 'json' ? 'json' : ext === 'py' ? 'python' : ext === 'html' ? 'html' : ext === 'js' ? 'javascript' : 'text';
                monaco.editor.setModelLanguage(editor.getModel(), language);
                editor.setValue(content);
                localStorage.setItem(`orig_${path}`, content);
                // Уведомляем СР об открытом файле
                addSystemMessage(`📁 Открыт файл: ${path}`, true);
            } catch (err) {
                editor.setValue(`// Ошибка загрузки: ${err.message}`);
            }
        }

        function saveCurrentFile() {
            const path = currentFilePath.textContent;
            if (!path) return;
            const content = editor.getValue();
            const patch = { file_path: path, content: content };
            if (ws && ws.readyState === WebSocket.OPEN) {
                ws.send(JSON.stringify({ type: 'apply_patch', patch: patch, session_id: currentChatId }));
                showToast('◈ изменения отправлены', 'success');
                localStorage.setItem(`orig_${path}`, content);
            } else {
                showToast('◈ нет соединения', 'error');
            }
        }

